mapper.delete:
DELETE FROM user_favorite
WHERE user_id = #{userId}
  AND post_id = #{postId}

mapper.select:
SELECT user_id, post_id, created_at
FROM user_favorite
WHERE user_id = #{userId}

    AND (
        created_at < #{cursorCreatedAt}
        OR (created_at = #{cursorCreatedAt} AND post_id < #{cursorPostId})
    )

ORDER BY created_at DESC, post_id DESC
LIMIT #{limit}
